        // in parkStaleSession) is too late to undo.
        loadConfigMock.mockReturnValue({ ...baseConfig(), staleAfterMinutes: 60 });
        mockClaudeJsonlState("waiting", { lastMtimeMs: STALE_PARK_ACTIVITY_MS });
